// ============================================================
// AGROSMART S3-03 - PREPARAR ANALISIS COMERCIAL
// Pipeline 3: precio + volumen + tendencia
// Mode: Run Once for All Items
// ============================================================

const filas = $input.all()
  .map(i => i.json ?? {})
  .filter(r =>
    ['GMML', 'MMF2'].includes(r.mercado) &&
    r.producto &&
    r.precio_actual != null
  );

// ------------------------------------------------------------
// 1. CLASIFICACION Y PREGUNTA
// ------------------------------------------------------------

let clase = {};

try {
  const fuente = $('Code - Normalizar clasificación').first().json;
  clase = typeof fuente.output === 'string'
    ? JSON.parse(fuente.output)
    : (fuente.output ?? fuente);
} catch (_) {
  const fuente = $('Switch1').first().json;
  clase = typeof fuente.output === 'string'
    ? JSON.parse(fuente.output)
    : (fuente.output ?? fuente);
}

const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);

const productoBuscado = clase.producto || null;

// ------------------------------------------------------------
// 2. FUNCIONES AUXILIARES
// ------------------------------------------------------------

const num = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const normal = s => String(s ?? '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const palabras = s =>
  normal(s).split(/[^a-z0-9]+/).filter(Boolean);

const fechaValor = v => String(v ?? '').slice(0, 10) || null;

const textoPregunta = normal(pregunta);

const nombreMercado = mercado =>
  mercado === 'MMF2'
    ? 'Mercado Mayorista de Frutas N.º 2 (MMF2)'
    : 'Gran Mercado Mayorista de Lima (GMML)';

// ------------------------------------------------------------
// 3. MERCADO SOLICITADO
// ------------------------------------------------------------

const mencionaGMML =
  /\bgmml\b|gran mercado mayorista/.test(textoPregunta);

const mencionaMMF2 =
  /\bmmf2\b|\bmmf\b|mercado mayorista de frutas/.test(textoPregunta);

const pideComparacion =
  /compar|ambos mercados|dos mercados|entre mercados/.test(textoPregunta);

const pideAmbos =
  pideComparacion || (mencionaGMML && mencionaMMF2);

const mercadoSolicitado = pideAmbos
  ? null
  : mencionaMMF2
    ? 'MMF2'
    : mencionaGMML
      ? 'GMML'
      : null;

const mercadosConsultados = mercadoSolicitado
  ? [mercadoSolicitado]
  : ['GMML', 'MMF2'];

// ------------------------------------------------------------
// 4. NORMALIZAR FILAS DEL SQL
// ------------------------------------------------------------

function resumen(d) {
  return {
    mercado: d.mercado,
    nombre_mercado: nombreMercado(d.mercado),
    producto: d.producto,
    producto_id: d.producto_id ?? null,
    unidad: d.unidad ?? null,

    fecha_ultimo_registro: fechaValor(d.fecha_ultimo_registro),
    precio_actual: num(d.precio_actual),
    precio_anterior: num(d.precio_anterior),
    precio_promedio_7: num(d.precio_promedio_7),
    precio_promedio_30: num(d.precio_promedio_30),
    tendencia_precio: d.tendencia_precio ?? null,

    fecha_ultimo_volumen: fechaValor(d.fecha_ultimo_volumen),
    volumen_ultimo_t: num(d.volumen_ultimo_t),
    volumen_actual_t: num(d.volumen_actual_t),
    volumen_promedio_7_t: num(d.volumen_promedio_7_t),
    volumen_promedio_30_t: num(d.volumen_promedio_30_t),

    registros_precio_7: num(d.registros_precio_7) ?? 0,
    registros_volumen_7: num(d.registros_volumen_7) ?? 0,
    total_registros_precio: num(d.total_registros_precio) ?? 0,
    total_registros_volumen: num(d.total_registros_volumen) ?? 0,

    dias_desde_precio: num(d.dias_desde_precio),
    desfase_precio_volumen_dias: num(d.desfase_precio_volumen_dias)
  };
}

const lista = filas.map(resumen);

const disponibles = mercadoSolicitado
  ? lista.filter(r => r.mercado === mercadoSolicitado)
  : lista;

// ============================================================
// 5. MODO GENERAL DEL MERCADO
// ============================================================

if (!productoBuscado) {
  const mercados = mercadoSolicitado
    ? [mercadoSolicitado]
    : ['GMML', 'MMF2'];

  const resultado = {};

  for (const mercado of mercados) {
    const registros = disponibles
      .filter(r =>
        r.mercado === mercado &&
        normal(r.unidad) === 'kilogramo' &&
        r.precio_actual !== null &&
        r.precio_actual > 0
      );

    const ultimaFecha = registros
      .map(r => r.fecha_ultimo_registro)
      .filter(Boolean)
      .sort()
      .at(-1) ?? null;

    const delDia = registros
      .filter(r => r.fecha_ultimo_registro === ultimaFecha)
      .map(r => {
        const variacion =
          r.precio_anterior !== null && r.precio_anterior > 0
            ? ((r.precio_actual - r.precio_anterior) / r.precio_anterior) * 100
            : null;

        return {
          producto: r.producto,
          precio_actual: r.precio_actual,
          unidad: r.unidad,
          tendencia: r.tendencia_precio,
          variacion_porcentual: variacion
        };
      });

    const conVariacion = delDia.filter(
      r => r.variacion_porcentual !== null
    );

    resultado[mercado] = {
      fecha: ultimaFecha,
      productos_analizados: delDia.length,
      mas_caros: [...delDia]
        .sort((a, b) => b.precio_actual - a.precio_actual)
        .slice(0, 2),
      mas_baratos: [...delDia]
        .sort((a, b) => a.precio_actual - b.precio_actual)
        .slice(0, 2),
      mayores_alzas: [...conVariacion]
        .filter(r => r.variacion_porcentual > 0)
        .sort((a, b) => b.variacion_porcentual - a.variacion_porcentual)
        .slice(0, 2),
      mayores_bajas: [...conVariacion]
        .filter(r => r.variacion_porcentual < 0)
        .sort((a, b) => a.variacion_porcentual - b.variacion_porcentual)
        .slice(0, 2)
    };
  }

  return [{
    json: {
      modo: 'general',
      pregunta_usuario: pregunta,
      mercados_consultados: mercados,
      resumen_mercados: resultado,
      nota: 'No emitir recomendaciones de venta para una consulta general.'
    }
  }];
}

// ============================================================
// 6. MODO ESPECIFICO: BUSCAR FAMILIA / VARIEDADES
// ============================================================

const buscadas = palabras(productoBuscado);

let candidatos = disponibles.filter(r => {
  const encontradas = palabras(r.producto);
  return buscadas.every(p => encontradas.includes(p));
});

// Si no hubo coincidencia por palabras completas, no ampliar de forma
// peligrosa. El LLM recibira una lista vacia y respondera sin inventar.

// ------------------------------------------------------------
// 7. UNIDAD COMERCIAL
// ------------------------------------------------------------

let unidadPedida = null;

if (/\b(kilogramos?|kilos?|kg)\b/.test(textoPregunta)) {
  unidadPedida = 'kilogramo';
} else if (/\batados?\b/.test(textoPregunta)) {
  unidadPedida = 'atado';
} else if (/\bdocenas?\b/.test(textoPregunta)) {
  unidadPedida = 'docena';
} else if (/\bcajones?\b/.test(textoPregunta)) {
  unidadPedida = 'cajon';
} else if (/\bjabas?\b/.test(textoPregunta)) {
  unidadPedida = 'jaba';
} else if (/\bsacos?\b/.test(textoPregunta)) {
  unidadPedida = 'saco';
}

if (unidadPedida) {
  candidatos = candidatos.filter(
    r => normal(r.unidad) === unidadPedida
  );
} else {
  // Sin unidad explicita: para cada producto y mercado,
  // preferir Kilogramo si existe. Esto evita duplicar una misma
  // variedad por Cajon/Atado/Kilogramo.
  const grupos = new Map();

  for (const r of candidatos) {
    const clave = `${r.mercado}|${normal(r.producto)}`;
    if (!grupos.has(clave)) grupos.set(clave, []);
    grupos.get(clave).push(r);
  }

  const preferidos = [];

  for (const items of grupos.values()) {
    const kg = items.filter(
      r => normal(r.unidad) === 'kilogramo'
    );

    if (kg.length) {
      preferidos.push(...kg);
    } else {
      // Si no existe Kilogramo, conservar una sola presentacion:
      // la que tenga mejor calidad de datos.
      const ordenados = [...items].sort((a, b) => {
        const qa = (a.registros_precio_7 * 2) + a.registros_volumen_7;
        const qb = (b.registros_precio_7 * 2) + b.registros_volumen_7;
        return qb - qa;
      });
      if (ordenados[0]) preferidos.push(ordenados[0]);
    }
  }

  candidatos = preferidos;
}

// Si la consulta es un producto generico de una sola palabra
// (por ejemplo, "papa") y existen variedades mas especificas,
// excluir la fila generica exacta para priorizar las variedades.
if (buscadas.length === 1) {
  const alternativas = candidatos.filter(
    r => normal(r.producto) !== normal(productoBuscado)
  );

  if (alternativas.length > 0) {
    candidatos = alternativas;
  }
}

// ============================================================
// 8. EVALUAR SUFICIENCIA Y DECISION BASE
// ============================================================

function evaluar(d) {
  const faltantes = [];

  if (d.registros_precio_7 < 5) {
    faltantes.push('Hay menos de 5 registros recientes de precio.');
  }

  if (d.registros_volumen_7 < 3) {
    faltantes.push('Hay menos de 3 registros de volumen para comparar.');
  }

  if (
    d.precio_anterior === null ||
    d.precio_promedio_7 === null ||
    d.precio_promedio_7 <= 0 ||
    d.precio_actual === null ||
    d.precio_actual <= 0
  ) {
    faltantes.push('No existe una comparacion reciente de precios valida.');
  }

  if (
    d.volumen_ultimo_t === null ||
    d.volumen_promedio_7_t === null ||
    d.volumen_promedio_7_t <= 0
  ) {
    faltantes.push('Falta volumen reciente o su promedio comparable.');
  }

  if (
    d.dias_desde_precio === null ||
    d.dias_desde_precio > 7
  ) {
    faltantes.push('El ultimo precio tiene mas de 7 dias de antiguedad.');
  }

  if (
    d.desfase_precio_volumen_dias === null ||
    d.desfase_precio_volumen_dias > 7
  ) {
    faltantes.push(
      'El ultimo volumen no corresponde a un periodo comparable con el precio.'
    );
  }

  const suficiente = faltantes.length === 0;
  let decisionBase = null;

  if (suficiente) {
    const relacionPrecio =
      d.precio_actual / d.precio_promedio_7;

    const relacionVolumen =
      d.volumen_ultimo_t / d.volumen_promedio_7_t;

    if (
      relacionPrecio >= 1.05 &&
      relacionVolumen <= 0.90
    ) {
      decisionBase = 'Vender ahora';
    } else if (
      relacionPrecio <= 0.95 &&
      relacionVolumen >= 1.10
    ) {
      decisionBase = 'Esperar y monitorear';
    } else {
      decisionBase = 'Vender parcialmente y monitorear';
    }
  }

  return {
    mercado: d.mercado,
    producto: d.producto,
    unidad: d.unidad,

    fecha_precio: d.fecha_ultimo_registro,
    precio_actual: d.precio_actual,
    precio_anterior: d.precio_anterior,
    promedio_precio_7: d.precio_promedio_7,
    promedio_precio_30: d.precio_promedio_30,
    tendencia: d.tendencia_precio,

    fecha_volumen: d.fecha_ultimo_volumen,
    volumen_ultimo_t: d.volumen_ultimo_t,
    promedio_volumen_7_t: d.volumen_promedio_7_t,
    promedio_volumen_30_t: d.volumen_promedio_30_t,

    registros_precio_7: d.registros_precio_7,
    registros_volumen_7: d.registros_volumen_7,

    estado: suficiente ? 'suficiente' : 'insuficiente',
    decision_base: decisionBase,
    faltantes
  };
}

const evaluados = candidatos.map(evaluar);

// ============================================================
// 9. SELECCIONAR HASTA 3 VARIEDADES / PRODUCTOS
// ============================================================

// Agrupar por nombre de producto. Una variedad puede conservar
// registros de ambos mercados; el limite de 3 aplica a variedades,
// no a filas mercado-producto.

const porProducto = new Map();

for (const ev of evaluados) {
  const clave = normal(ev.producto);
  if (!porProducto.has(clave)) porProducto.set(clave, []);
  porProducto.get(clave).push(ev);
}

function puntajeEvaluacion(ev) {
  let score = 0;

  if (ev.estado === 'suficiente') score += 100;
  score += Math.min(ev.registros_precio_7, 7) * 5;
  score += Math.min(ev.registros_volumen_7, 7) * 4;

  const dias = lista.find(r =>
    r.mercado === ev.mercado &&
    normal(r.producto) === normal(ev.producto) &&
    normal(r.unidad) === normal(ev.unidad)
  )?.dias_desde_precio;

  if (dias !== null && dias !== undefined) {
    if (dias <= 2) score += 20;
    else if (dias <= 7) score += 12;
    else if (dias <= 14) score += 4;
  }

  // Para consultas de mas de una palabra, premiar coincidencia exacta.
  if (
    buscadas.length > 1 &&
    normal(ev.producto) === normal(productoBuscado)
  ) {
    score += 30;
  }

  return score;
}

const rankingProductos = [...porProducto.entries()]
  .map(([clave, items]) => ({
    clave,
    producto: items[0]?.producto ?? clave,
    items,
    score: Math.max(...items.map(puntajeEvaluacion)),
    fechaMasReciente: items
      .map(x => x.fecha_precio)
      .filter(Boolean)
      .sort()
      .at(-1) ?? ''
  }))
  .sort((a, b) =>
    b.score - a.score ||
    b.fechaMasReciente.localeCompare(a.fechaMasReciente) ||
    a.producto.localeCompare(b.producto)
  );

const seleccionProductos = rankingProductos.slice(0, 3);

const seleccionados = seleccionProductos
  .flatMap(x => x.items)
  .sort((a, b) =>
    a.producto.localeCompare(b.producto) ||
    a.mercado.localeCompare(b.mercado)
  );

// ============================================================
// 10. SALIDA COMPACTA PARA EL LLM
// ============================================================

return [{
  json: {
    modo: 'especifico',
    pregunta_usuario: pregunta,
    producto_solicitado: productoBuscado,
    mercados_consultados: mercadosConsultados,

    total_variedades_encontradas: rankingProductos.length,
    variedades_seleccionadas: seleccionProductos.map(x => x.producto),

    analisis: seleccionados,

    reglas_contexto: {
      maximo_variedades: 3,
      clima_incluido: false,
      usar_decision_base: true
    }
  }
}];

