const respuesta = $input.first().json;

const vector = respuesta.data?.[0]?.embedding;

if (!Array.isArray(vector) || vector.length === 0) {
  throw new Error(
    'No se pudo obtener el embedding de Jina AI'
  );
}

if (vector.length !== 384) {
  throw new Error(
    `Dimensión inesperada: ${vector.length}. Se esperaban 384 dimensiones.`
  );
}

return [{
  json: {
    dimension: vector.length,
    embedding: `[${vector.join(',')}]`
  }
}];

// ============================================================
// AGROSMART - CONTEXTO RAG V2
// Pipeline 5: RAG + datos estructurados
// Objetivo: reducir tokens sin perder evidencia.
// Mode: Run Once for All Items
// ============================================================

const filas = $input.all().map(
  item => item.json ?? {}
);


// ------------------------------------------------------------
// 1. CLASIFICACIÓN Y PREGUNTA
// ------------------------------------------------------------

function parseSalida(valor) {

  if (typeof valor === 'string') {

    try {
      return JSON.parse(valor);
    } catch (_) {
      return {};
    }
  }

  return (
    valor &&
    typeof valor === 'object'
  )
    ? valor
    : {};
}


let clasificacion = {};


try {

  const nodo =
    $('Code - Normalizar clasificación')
      .first()
      .json ?? {};

  clasificacion =
    parseSalida(
      nodo.output ?? nodo
    );

} catch (_) {

  try {

    const nodo =
      $('Switch1')
        .first()
        .json ?? {};

    clasificacion =
      parseSalida(
        nodo.output ?? nodo
      );

  } catch (_) {

    clasificacion = {};
  }
}


const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
).trim();


const producto =
  clasificacion.producto ??
  filas[0]?.producto_solicitado ??
  null;


const fecha =
  clasificacion.fecha ??
  filas[0]?.fecha_solicitada ??
  null;


// ------------------------------------------------------------
// 2. FUNCIONES AUXILIARES
// ------------------------------------------------------------

function normalizar(texto) {

  return String(texto ?? '')

    .normalize('NFD')

    .replace(
      /[\u0300-\u036f]/g,
      ''
    )

    .toLowerCase()

    .replace(
      /\s+/g,
      ' '
    )

    .trim();
}


function limpiarTexto(texto) {

  return String(texto ?? '')

    .replace(
      /\r/g,
      ' '
    )

    .replace(
      /[ \t]+/g,
      ' '
    )

    .replace(
      /\n{3,}/g,
      '\n\n'
    )

    .trim();
}


function parseMetadata(valor) {

  if (!valor) {
    return {};
  }

  if (
    typeof valor === 'object'
  ) {
    return valor;
  }

  try {

    return JSON.parse(valor);

  } catch (_) {

    return {};
  }
}


function numero(v) {

  if (
    v === null ||
    v === undefined ||
    v === ''
  ) {
    return null;
  }

  const n = Number(v);

  return Number.isFinite(n)
    ? n
    : null;
}


// ------------------------------------------------------------
// 3. TÉRMINOS RELEVANTES DE LA CONSULTA
// ------------------------------------------------------------

const stopwords = new Set([

  'que',
  'cual',
  'cuales',
  'como',
  'cuando',
  'donde',
  'sobre',
  'segun',

  'del',
  'de',
  'la',
  'las',
  'los',
  'el',

  'un',
  'una',
  'unos',
  'unas',

  'por',
  'para',
  'con',
  'sin',
  'en',
  'al',

  'se',
  'su',
  'sus',
  'me',

  'dime',
  'dame',
  'muestra',
  'muestrame',

  'informacion',
  'relevante',

  'boletin',
  'boletines',

  'documento',
  'documentos',

  'agricola',
  'agricolas',

  'almacenado',
  'almacenados',

  'aparece',
  'dicen',
  'menciona',
  'reporta'
]);


function construirTerminos() {

  const terminos = [];


  const productoNormal =
    normalizar(producto);


  if (productoNormal) {

    // Priorizar primero el nombre completo.
    terminos.push(
      productoNormal
    );


    for (
      const palabra
      of productoNormal.split(
        /[^a-z0-9]+/
      )
    ) {

      if (
        palabra.length >= 3
      ) {

        terminos.push(
          palabra
        );
      }
    }
  }


  const palabrasPregunta =
    normalizar(pregunta)

      .split(
        /[^a-z0-9]+/
      )

      .filter(Boolean)

      .filter(
        p =>
          p.length >= 4
      )

      .filter(
        p =>
          !stopwords.has(p)
      );


  terminos.push(
    ...palabrasPregunta
  );


  return [
    ...new Set(
      terminos
    )
  ]

    .sort(
      (a, b) =>
        b.length -
        a.length
    )

    .slice(
      0,
      10
    );
}


const terminosBusqueda =
  construirTerminos();


// ------------------------------------------------------------
// 4. EXTRAER FRAGMENTOS RELEVANTES
// ------------------------------------------------------------

// Este proceso NO resume mediante IA.
//
// Conserva texto literal del documento,
// pero solo las partes próximas a los términos
// relevantes de la consulta.

function extraerFragmento(
  texto,
  maxChars = 900
) {

  const contenido =
    limpiarTexto(texto);


  if (!contenido) {
    return '';
  }


  if (
    contenido.length <= maxChars
  ) {

    return contenido;
  }


  const simple =
    normalizar(contenido);


  const posiciones = [];


  for (
    const termino
    of terminosBusqueda
  ) {

    let desde = 0;

    let encontrados = 0;


    // Máximo dos apariciones
    // por término.

    while (
      encontrados < 2
    ) {

      const idx =
        simple.indexOf(
          termino,
          desde
        );


      if (
        idx === -1
      ) {
        break;
      }


      posiciones.push({

        inicio:
          Math.max(
            0,
            idx - 140
          ),

        fin:
          Math.min(
            contenido.length,
            idx +
            termino.length +
            280
          )
      });


      desde =
        idx +
        termino.length;


      encontrados += 1;
    }
  }


  // Si no apareció ningún término,
  // conservar el inicio del chunk que
  // PGVector consideró relevante.

  if (
    !posiciones.length
  ) {

    return (
      contenido
        .slice(
          0,
          maxChars
        )
        .trim()
      +
      ' […]'
    );
  }


  posiciones.sort(
    (a, b) =>
      a.inicio -
      b.inicio
  );


  // Fusionar ventanas que se superponen.

  const fusionadas = [];


  for (
    const ventana
    of posiciones
  ) {

    const ultima =
      fusionadas.at(-1);


    if (
      ultima &&
      ventana.inicio <=
      ultima.fin + 60
    ) {

      ultima.fin =
        Math.max(
          ultima.fin,
          ventana.fin
        );

    } else {

      fusionadas.push({
        ...ventana
      });
    }
  }


  const partes = [];

  let usados = 0;


  for (
    const ventana
    of fusionadas
  ) {

    if (
      usados >= maxChars
    ) {
      break;
    }


    const disponible =
      maxChars -
      usados;


    let fragmento =
      contenido

        .slice(
          ventana.inicio,
          ventana.fin
        )

        .trim();


    if (
      fragmento.length >
      disponible
    ) {

      fragmento =
        fragmento

          .slice(
            0,
            disponible
          )

          .trim();
    }


    if (
      fragmento
    ) {

      partes.push(
        fragmento
      );

      usados +=
        fragmento.length;
    }
  }


  return (
    partes.join(
      '\n[…]\n'
    )
    ||
    contenido
      .slice(
        0,
        maxChars
      )
      .trim()
  );
}


// ------------------------------------------------------------
// 5. DOCUMENTOS RAG
// ------------------------------------------------------------

const documentosValidos =
  filas

    .filter(
      f =>
        f.id != null &&
        typeof f.text === 'string' &&
        f.text.trim()
    )

    .sort(
      (a, b) => {

        const da =
          numero(
            a.distancia_coseno
          );

        const db =
          numero(
            b.distancia_coseno
          );


        if (
          da === null &&
          db === null
        ) {
          return 0;
        }


        if (
          da === null
        ) {
          return 1;
        }


        if (
          db === null
        ) {
          return -1;
        }


        return da - db;
      }
    );


// ------------------------------------------------------------
// 6. DEDUPLICAR DOCUMENTOS
// ------------------------------------------------------------

// PostgreSQL sigue recuperando hasta cinco.
//
// Aquí NO bajamos todavía ese límite.
// Solo evitamos enviar el mismo ID dos veces.

const idsVistos =
  new Set();


const documentosUnicos =
  [];


for (
  const doc
  of documentosValidos
) {

  const clave =
    String(
      doc.id
    );


  if (
    idsVistos.has(
      clave
    )
  ) {
    continue;
  }


  idsVistos.add(
    clave
  );


  documentosUnicos.push(
    doc
  );


  if (
    documentosUnicos.length >= 5
  ) {
    break;
  }
}


// ------------------------------------------------------------
// 7. AGRUPAR CHUNKS DE LA MISMA FUENTE
// ------------------------------------------------------------

const grupos =
  new Map();


for (
  const doc
  of documentosUnicos
) {

  const metadata =
    parseMetadata(
      doc.metadata
    );


  // IMPORTANTE:
  // No inventamos un nombre de boletín
  // cuando metadata no lo contiene.

  const fuente =

    metadata.filename ??

    metadata.archivo ??

    metadata.titulo ??

    metadata.fuente ??

    null;


  const fechaDocumento =

    metadata.fecha ??

    metadata.date ??

    null;


  const fragmento =
    extraerFragmento(
      doc.text,
      900
    );


  if (
    !fragmento
  ) {
    continue;
  }


  const claveGrupo =

    `${fuente ?? 'SIN_FUENTE'}|` +
    `${fechaDocumento ?? 'SIN_FECHA'}`;


  if (
    !grupos.has(
      claveGrupo
    )
  ) {

    grupos.set(
      claveGrupo,
      {

        fuente,

        fecha:
          fechaDocumento,

        fragmentos: []
      }
    );
  }


  const grupo =
    grupos.get(
      claveGrupo
    );


  if (
    !grupo.fragmentos.includes(
      fragmento
    )
  ) {

    grupo.fragmentos.push(
      fragmento
    );
  }
}


// ------------------------------------------------------------
// 8. LIMITAR CONTEXTO DOCUMENTAL
// ------------------------------------------------------------

// No quitamos las fuentes recuperadas,
// pero evitamos enviar miles de caracteres
// repetidos del mismo documento.

const evidencias = [];

let caracteresDocumentales =
  0;


const MAX_TOTAL_DOCUMENTAL =
  4500;


const MAX_POR_FUENTE =
  1300;


for (
  const grupo
  of grupos.values()
) {

  if (
    caracteresDocumentales >=
    MAX_TOTAL_DOCUMENTAL
  ) {
    break;
  }


  let textoGrupo =
    grupo.fragmentos

      .join(
        '\n[…]\n'
      )

      .trim();


  textoGrupo =
    textoGrupo

      .slice(

        0,

        Math.min(

          MAX_POR_FUENTE,

          MAX_TOTAL_DOCUMENTAL -
          caracteresDocumentales
        )
      )

      .trim();


  if (
    !textoGrupo
  ) {
    continue;
  }


  caracteresDocumentales +=
    textoGrupo.length;


  evidencias.push({

    fuente:
      grupo.fuente,

    fecha:
      grupo.fecha,

    fragmento:
      textoGrupo
  });
}


// ------------------------------------------------------------
// 9. DATOS ESTRUCTURADOS
// ------------------------------------------------------------

let precios =
  filas[0]?.datos_precios ??
  [];


if (
  typeof precios === 'string'
) {

  try {

    precios =
      JSON.parse(
        precios
      );

  } catch (_) {

    precios = [];
  }
}


if (
  !Array.isArray(
    precios
  )
) {

  precios = [];
}


// ------------------------------------------------------------
// 10. DEDUPLICAR DATOS ESTRUCTURADOS
// ------------------------------------------------------------

// Conservamos hasta 25, igual que antes.
//
// No bajamos agresivamente este límite
// porque estos valores son datos verificados.

const clavesPrecios =
  new Set();


const registrosEstructurados =
  [];


for (
  const p
  of precios
) {

  const clave = [

    p.fecha ?? '',

    p.producto ?? '',

    p.unidad ?? '',

    p.precio ?? '',

    p.volumen_t ?? '',

    p.equivalencia_kg ?? ''

  ].join('|');


  if (
    clavesPrecios.has(
      clave
    )
  ) {
    continue;
  }


  clavesPrecios.add(
    clave
  );


  const partes = [

    p.fecha
      ? `fecha=${p.fecha}`
      : null,

    p.producto
      ? `producto=${p.producto}`
      : null,

    p.precio != null
      ? `precio=${p.precio}`
      : null,

    p.unidad
      ? `unidad=${p.unidad}`
      : null,

    p.volumen_t != null
      ? `volumen_t=${p.volumen_t}`
      : null,

    p.equivalencia_kg != null
      ? `equivalencia_kg=${p.equivalencia_kg}`
      : null

  ].filter(
    Boolean
  );


  if (
    partes.length
  ) {

    registrosEstructurados.push(
      partes.join(
        '; '
      )
    );
  }


  if (
    registrosEstructurados.length >= 25
  ) {
    break;
  }
}


// ------------------------------------------------------------
// 11. CONTEXTO FINAL COMPACTO
// ------------------------------------------------------------

const bloques =
  [];


// CONSULTA

bloques.push(

  [

    `PREGUNTA: ${pregunta}`,

    `PRODUCTO: ${
      producto ??
      'no especificado'
    }`,

    `FECHA SOLICITADA: ${
      fecha ??
      'no especificada'
    }`

  ].join(
    '\n'
  )
);


// DATOS ESTRUCTURADOS

bloques.push(

  'DATOS ESTRUCTURADOS VERIFICADOS:\n'

  +

  (
    registrosEstructurados.length

      ? registrosEstructurados

          .map(
            (r, i) =>
              `${i + 1}. ${r}`
          )

          .join(
            '\n'
          )

      : 'No hay datos estructurados verificados para esta combinación de producto y fecha.'
  )
);


// EVIDENCIA DOCUMENTAL

bloques.push(

  'EVIDENCIAS DOCUMENTALES RECUPERADAS:\n'

  +

  (
    evidencias.length

      ? evidencias

          .map(
            (e, i) => {

              const cabecera = [

                `[${i + 1}]`,

                `fuente=${
                  e.fuente ??
                  'no especificada'
                }`,

                `fecha=${
                  e.fecha ??
                  'no especificada'
                }`

              ].join(
                ' | '
              );


              return (
                `${cabecera}\n` +
                `${e.fragmento}`
              );
            }
          )

          .join(
            '\n\n---\n\n'
          )

      : 'No se recuperaron fragmentos documentales válidos.'
  )
);


const contexto =
  bloques.join(
    '\n\n'
  );


// ------------------------------------------------------------
// 12. SALIDA
// ------------------------------------------------------------

return [{
  json: {

    pregunta_usuario:
      pregunta,

    producto_solicitado:
      producto,

    fecha_solicitada:
      fecha,

    documentos_recuperados:
      documentosUnicos.length,

    fuentes_documentales:
      evidencias.length,

    precios_recuperados:
      registrosEstructurados.length,

    contexto
  }
}];

/**
 * AGROSMART WF2 - ARMAR RESPUESTA PRECIOS
 * GMML y MMF2
 * Mode: Run Once for All Items
 */

const filas = $input.all().map(i => i.json ?? {});

const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);

const norm = v => String(v ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

const palabras = v => norm(v)
  .split(/[^a-z0-9]+/)
  .filter(Boolean);

const numero = v => {
  if (v == null || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : null;
};

const dinero = v => `S/ ${Number(v).toFixed(2)}`;

const fechaCorta = f => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(f))) {
    return String(f ?? '');
  }

  const [a, m, d] = f.split('-');
  return `${d}/${m}/${a}`;
};

const nombreMercado = m => m === 'MMF2'
  ? 'Mercado Mayorista de Frutas N.º 2 (MMF2)'
  : 'Gran Mercado Mayorista de Lima (GMML)';

const texto = norm(pregunta);

// CLASIFICACION

let clase = {};

try {
  const origen = $('Code - Normalizar clasificación').first().json;
  clase = typeof origen.output === 'string'
    ? JSON.parse(origen.output)
    : (origen.output ?? origen);
} catch (e) {
  try {
    const origen = $('Switch1').first().json;
    clase = typeof origen.output === 'string'
      ? JSON.parse(origen.output)
      : (origen.output ?? origen);
  } catch (e2) {
    clase = {};
  }
}

const producto = String(
  clase.producto ??
  filas.find(f => f.producto)?.producto ??
  'producto consultado'
);

const buscado = norm(producto);
const buscadas = palabras(buscado);

const fechaSolicitada =
  clase.fecha ??
  filas.find(f => f.fecha_consultada)?.fecha_consultada ??
  null;

const fechaFin =
  filas.find(f => f.fecha_fin_semana)?.fecha_fin_semana ??
  fechaSolicitada;

// INTENCION

const semanalSQL = filas.some(f =>
  f.consulta_semanal === true ||
  String(f.consulta_semanal).toLowerCase() === 'true'
);

const semanalPregunta =
  /ultimos?\s+(7|siete)\s+(dias|precios|registros)|ultima\s+semana|esta\s+semana|semanal|durante\s+la\s+semana/
    .test(texto);

const semanal = semanalSQL || semanalPregunta;

const pideVariacion =
  /variacion|variaron|vario|evolucion|subio|bajo|aumento|disminuyo|tendencia/
    .test(texto);

const pideHistorial =
  /anteriores|historico|historial|ultimos?\s+\d+\s+precios/
    .test(texto);

const pideTodas =
  /todas\s+las\s+variedades|lista\s+completa|todos\s+los\s+precios|detalle\s+completo/
    .test(texto);

const gmml = /\bgmml\b|gran mercado mayorista/.test(texto);
const mmf2 = /\bmmf2\b|\bmmf\b|mercado mayorista de frutas/.test(texto);

const comparar =
  /compar|ambos mercados|dos mercados|entre mercados|mas barato/
    .test(texto);

const ambos = comparar || (gmml && mmf2);

const mercadoElegido = ambos
  ? null
  : gmml ? 'GMML'
  : mmf2 ? 'MMF2'
  : null;

// UNIDAD PEDIDA

let unidadPedida = null;

if (/\b(kilogramos?|kilos?|kg)\b/.test(texto)) {
  unidadPedida = 'kilogramo';
} else if (/\batados?\b/.test(texto)) {
  unidadPedida = 'atado';
} else if (/\bdocenas?\b/.test(texto)) {
  unidadPedida = 'docena';
} else if (/\bcajones?\b/.test(texto)) {
  unidadPedida = 'cajon';
} else if (/\bjabas?\b/.test(texto)) {
  unidadPedida = 'jaba';
}

// REGISTROS VALIDOS

const validos = filas.filter(f => {
  if (!['GMML', 'MMF2'].includes(f.mercado)) return false;
  if (!f.producto || !f.fecha || numero(f.precio) === null) {
    return false;
  }

  if (mercadoElegido && f.mercado !== mercadoElegido) {
    return false;
  }

  const encontradas = palabras(f.producto);

  if (
    buscadas.length &&
    !buscadas.every(p => encontradas.includes(p))
  ) {
    return false;
  }

  if (fechaSolicitada && f.fecha > fechaSolicitada) {
    return false;
  }

  if (semanal && fechaFin && f.fecha > fechaFin) {
    return false;
  }

  return true;
});

// AGRUPAR POR MERCADO, VARIEDAD Y UNIDAD

const mapa = new Map();

for (const f of validos) {
  const clave = [
    f.mercado,
    f.producto_id ?? norm(f.producto),
    norm(f.unidad)
  ].join('|');

  if (!mapa.has(clave)) {
    mapa.set(clave, {
      mercado: f.mercado,
      producto: f.producto,
      producto_id: f.producto_id ?? null,
      unidad: f.unidad ?? 'unidad',
      dias: new Map()
    });
  }

  const grupo = mapa.get(clave);

  if (!grupo.dias.has(f.fecha)) {
    grupo.dias.set(f.fecha, numero(f.precio));
  }
}

let grupos = [...mapa.values()];

// Para variedad especifica, preferir coincidencia exacta
// en cada mercado, sin excluir el otro mercado.

grupos = grupos.filter(g => {
  const mismoMercado = grupos.filter(
    x => x.mercado === g.mercado
  );

  const hayExacto = mismoMercado.some(
    x => norm(x.producto) === buscado
  );

  return !hayExacto || norm(g.producto) === buscado;
});

// Respetar unidad explicita.
// Si no se indica, priorizar Kilogramo por mercado.

if (unidadPedida) {
  grupos = grupos.filter(
    g => norm(g.unidad) === unidadPedida
  );
} else {
  grupos = grupos.filter(g => {
    const tieneKg = grupos.some(
      x => x.mercado === g.mercado &&
           norm(x.unidad) === 'kilogramo'
    );

    return !tieneKg || norm(g.unidad) === 'kilogramo';
  });
}

// Ordenar registros y limitar a 7 si es semanal.

for (const g of grupos) {
  g.registros = [...g.dias.entries()]
    .map(([fecha, precio]) => ({ fecha, precio }))
    .sort((a, b) => b.fecha.localeCompare(a.fecha))
    .slice(0, semanal ? 7 : 4);

  g.actual = g.registros[0] ?? null;
}

grupos = grupos.filter(g => g.actual);

grupos.sort((a, b) =>
  b.actual.fecha.localeCompare(a.actual.fecha) ||
  a.producto.localeCompare(b.producto)
);

const orden = ['GMML', 'MMF2'];

const mercadosConDatos = orden.filter(m =>
  grupos.some(g => g.mercado === m)
);

const mercadosMostrar = mercadoElegido
  ? [mercadoElegido]
  : ambos ? orden : mercadosConDatos;

const partes = [];
let variedadesMostradas = 0;

function agregar(texto) {
  if (texto) partes.push(texto);
}

// RESPUESTAS SEMANALES / SIETE REGISTROS

if (semanal) {

  agregar(`Últimos precios disponibles de ${producto}`);

  agregar(
    `Consulta: hasta 7 registros históricos por variedad` +
    (fechaFin ? `, hasta el ${fechaCorta(fechaFin)}` : '') +
    '. Las fechas pueden abarcar más de una semana.'
  );

  if (!semanalSQL) {
    agregar(
      'Aviso: el SQL no confirmó el modo semanal. ' +
      'Verifica que PRECIOS1 esté recuperando siete registros.'
    );
  }

  for (const mercado of mercadosMostrar) {

    let candidatos = grupos.filter(g => g.mercado === mercado);

    agregar(nombreMercado(mercado));

    if (!candidatos.length) {
      agregar(
        'No encontré registros para esta variedad y unidad.'
      );
      continue;
    }

    // En consultas generales mostrar todas las variedades.
    // Cada variedad tiene como maximo siete registros.
    for (const g of candidatos) {

      variedadesMostradas++;

      agregar(`${g.producto} — ${g.unidad}`);

      const dias = [...g.registros].sort(
        (a, b) => a.fecha.localeCompare(b.fecha)
      );

      const inicial = dias[0];
      const final = dias[dias.length - 1];

      if (!pideVariacion) {
        agregar(
          dias.map(r =>
            `${fechaCorta(r.fecha)}: ${dinero(r.precio)}`
          ).join('\n')
        );
      } else {
        agregar(
          `Precio inicial (${fechaCorta(inicial.fecha)}): ` +
          dinero(inicial.precio)
        );

        agregar(
          `Precio final (${fechaCorta(final.fecha)}): ` +
          dinero(final.precio)
        );
      }

      if (dias.length >= 2 && inicial.precio > 0) {

        const variacion =
          ((final.precio - inicial.precio) /
           inicial.precio) * 100;

        const signo = variacion > 0 ? '+' : '';

        const tendencia = variacion > 0
          ? 'subió'
          : variacion < 0 ? 'bajó'
          : 'se mantuvo estable';

        agregar(
          `Variación entre registros: ` +
          `${signo}${variacion.toFixed(2)} % (${tendencia}).`
        );

      } else {
        agregar(
          'No hay suficientes registros para calcular la variación.'
        );
      }

      agregar(
        `Registros históricos recuperados: ${dias.length} de un máximo de 7.`
      );
    }
  }

} else {

  // CONSULTAS PUNTUALES

  agregar(`Precios de ${producto}`);

  for (const mercado of mercadosMostrar) {

    let candidatos = grupos.filter(
      g => g.mercado === mercado
    );

    agregar(nombreMercado(mercado));

    if (!candidatos.length) {
      agregar(
        'No encontré precios registrados para el producto ' +
        'y la fecha consultados.'
      );
      continue;
    }

    // Priorizar el dia solicitado si existe.
    const enFecha = candidatos.filter(g =>
      g.actual.fecha === fechaSolicitada
    );

    if (enFecha.length && !pideTodas) {
      candidatos = enFecha;
    }

    if (!pideTodas) {
      candidatos = candidatos.slice(0, 5);
    }

    variedadesMostradas += candidatos.length;

    for (const g of candidatos) {
      const r = g.actual;

      const fechaExtra =
        r.fecha === fechaSolicitada
          ? ''
          : ` (registro del ${fechaCorta(r.fecha)})`;

      agregar(
        `${g.producto}: ${dinero(r.precio)} por ` +
        `${g.unidad}${fechaExtra}`
      );

      if (pideHistorial) {
        const anteriores = g.registros.slice(1, 4);

        if (anteriores.length) {
          agregar(
            'Precios anteriores: ' +
            anteriores.map(x =>
              `${fechaCorta(x.fecha)}: ${dinero(x.precio)}`
            ).join('; ')
          );
        }
      }
    }
  }
}

// COMPARACION DIRECTA ENTRE MERCADOS

if (comparar &&
    mercadosConDatos.includes('GMML') &&
    mercadosConDatos.includes('MMF2')) {

  const a = grupos.filter(g => g.mercado === 'GMML');
  const b = grupos.filter(g => g.mercado === 'MMF2');

  const pares = [];

  for (const x of a) {
    for (const y of b) {

      const mismoProducto =
        x.producto_id != null && y.producto_id != null
          ? String(x.producto_id) === String(y.producto_id)
          : norm(x.producto) === norm(y.producto);

      if (!mismoProducto ||
          norm(x.unidad) !== norm(y.unidad)) {
        continue;
      }

      for (const rx of x.registros) {
        const ry = y.registros.find(
          r => r.fecha === rx.fecha
        );

        if (ry) {
          pares.push({
            producto: x.producto,
            unidad: x.unidad,
            fecha: rx.fecha,
            gmml: rx.precio,
            mmf2: ry.precio
          });
        }
      }
    }
  }

  pares.sort((x, y) => y.fecha.localeCompare(x.fecha));

  if (pares.length) {
    const p = pares[0];
    const diferencia = Math.abs(p.gmml - p.mmf2);

    const barato =
      p.gmml < p.mmf2 ? 'GMML'
      : p.mmf2 < p.gmml ? 'MMF2'
      : null;

    agregar(
      `Comparación directa del ${fechaCorta(p.fecha)}: ` +
      `${p.producto} (${p.unidad}).`
    );

    agregar(`GMML: ${dinero(p.gmml)}`);
    agregar(`MMF2: ${dinero(p.mmf2)}`);

    agregar(
      barato
        ? `Diferencia: ${dinero(diferencia)} menos en ${barato}.`
        : 'Los precios fueron iguales.'
    );

  } else {
    agregar(
      'No hay registros directamente comparables para la ' +
      'misma variedad, fecha y unidad.'
    );
  }
}

if (!mercadosConDatos.length) {
  agregar(
    'No se encontraron precios disponibles para la consulta.'
  );
}

agregar('Fuente: MIDAGRI · AgroSmart Insights.');

// RESPUESTA EN TEXTO LIMPIO PARA VERCEL

const respuesta = partes.join('\n\n')
  .replace(/^#{1,6}\s*/gm, '')
  .replace(/\*\*/g, '')
  .replace(/^-\s+/gm, '')
  .replace(/^_(.*)_$/gm, '$1')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{
  json: {
    respuesta,
    pregunta_usuario: pregunta,
    producto_solicitado: producto,
    tipo_consulta: semanal ? 'semanal' : 'puntual',
    consulta_semanal: semanal,
    sql_semanal_confirmado: semanalSQL,
    fecha_consultada: fechaSolicitada,
    fecha_fin_semana: semanal ? fechaFin : null,
    mercados_consultados: mercadosMostrar,
    mercados_con_datos: mercadosConDatos,
    registros_recuperados: validos.length,
    variedades_mostradas: variedadesMostradas
  }
}];

// ==========================================
// PREPARAR ERROR PARA LANGFUSE
// ==========================================

function hexAleatorio(bytes) {
  let resultado = '';

  for (let i = 0; i < bytes; i++) {
    resultado += Math
      .floor(Math.random() * 256)
      .toString(16)
      .padStart(2, '0');
  }

  return resultado;
}


// ==========================================
// TRACE ID DE LA CONSULTA
// ==========================================

let traceId = null;

try {
  traceId =
    $('Code - Inicio Trace')
      .first()
      .json
      .langfuse_trace_id;
} catch (error) {
  traceId = null;
}


// ==========================================
// PREGUNTA DEL USUARIO
// ==========================================

let pregunta = null;

try {
  pregunta =
    $('Webhook')
      .first()
      .json
      .body
      .pregunta ?? null;
} catch (error) {
  pregunta = null;
}


// ==========================================
// TIPO DE CONSULTA
// ==========================================

let tipoConsulta = 'desconocido';

try {
  const salidaAgent =
    $('AI Agent2')
      .first()
      .json
      .output;

  const clasificacion =
    typeof salidaAgent === 'string'
      ? JSON.parse(salidaAgent)
      : salidaAgent;

  tipoConsulta =
    clasificacion?.tipo_consulta ??
    'desconocido';

} catch (error) {
  tipoConsulta = 'desconocido';
}


// ==========================================
// EXTRAER ERROR RECIBIDO
// ==========================================

const errorEntrada =
  $json.error ??
  $json.message ??
  $json.description ??
  $json;


// ==========================================
// CONVERTIR ERROR A TEXTO SEGURO
// ==========================================

let errorTexto = '';

try {
  errorTexto =
    typeof errorEntrada === 'string'
      ? errorEntrada
      : JSON.stringify(errorEntrada);
} catch (error) {
  errorTexto = 'Error no serializable';
}


// ==========================================
// SANITIZAR DATOS SENSIBLES
// ==========================================

errorTexto = errorTexto
  .replace(/sk-[A-Za-z0-9_-]+/gi, '[REDACTED_API_KEY]')
  .replace(/Bearer\s+[A-Za-z0-9._-]+/gi, 'Bearer [REDACTED]')
  .replace(/postgres(?:ql)?:\/\/[^"\s]+/gi, '[REDACTED_DATABASE_URL]')
  .replace(/password["'=:\s]+[^,\s"}]+/gi, 'password=[REDACTED]')
  .slice(0, 1500);


// ==========================================
// CLASIFICAR ERROR
// ==========================================

let tipoError = 'ERROR_GENERAL';

const textoLower =
  errorTexto.toLowerCase();

if (
  textoLower.includes('429') ||
  textoLower.includes('rate limit')
) {
  tipoError = 'HTTP_429';
}

else if (
  textoLower.includes('timeout') ||
  textoLower.includes('timed out')
) {
  tipoError = 'TIMEOUT';
}

else if (
  textoLower.includes('postgres') ||
  textoLower.includes('database') ||
  textoLower.includes('connection refused') ||
  textoLower.includes('connection terminated')
) {
  tipoError = 'DATABASE_ERROR';
}

else if (
  textoLower.includes('openrouter') ||
  textoLower.includes('llm') ||
  textoLower.includes('model')
) {
  tipoError = 'LLM_ERROR';
}


// ==========================================
// MENSAJE CONTROLADO PARA EL USUARIO
// ==========================================

let mensajeUsuario =
  'No se pudo procesar la consulta en este momento. Intenta nuevamente más tarde.';

if (tipoError === 'HTTP_429') {
  mensajeUsuario =
    'El servicio de inteligencia artificial está temporalmente ocupado. Intenta nuevamente en unos segundos.';
}

else if (tipoError === 'TIMEOUT') {
  mensajeUsuario =
    'La consulta tardó más de lo esperado. Intenta nuevamente en unos segundos.';
}

else if (tipoError === 'DATABASE_ERROR') {
  mensajeUsuario =
    'No se pudo consultar la información almacenada en este momento. Intenta nuevamente más tarde.';
}


// ==========================================
// TIMESTAMP
// ==========================================

const ahoraMs = Date.now();


// ==========================================
// RETORNO
// ==========================================

return [{
  json: {

    trace_id:
      traceId ?? hexAleatorio(16),

    span_id:
      hexAleatorio(8),

    nombre_observacion:
      'AgroSmart - Error',

    tipo_consulta:
      tipoConsulta,

    tipo_error:
      tipoError,

    pregunta:
      pregunta,

    error_detalle:
      errorTexto,

    mensaje_usuario:
      mensajeUsuario,

    inicio_ns:
      (BigInt(ahoraMs - 1) * 1000000n).toString(),

    fin_ns:
      (BigInt(ahoraMs) * 1000000n).toString(),

    level:
      'ERROR'
  }
}];

