// ======================================================
// AGROSMART - VALIDAR CONSULTA V2
// Evita falsos positivos y tolera texto UTF-8 mal decodificado
// Mode: Run Once for All Items
// ======================================================

const preguntaOriginal = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);


// ------------------------------------------------------
// 1. NORMALIZACIÓN
// ------------------------------------------------------

function normalizar(texto) {
  return String(texto ?? '')

    // Mojibake UTF-8 frecuente
    .replace(/Ã¡/gi, 'a')
    .replace(/Ã©/gi, 'e')
    .replace(/Ã­/gi, 'i')
    .replace(/Ã³/gi, 'o')
    .replace(/Ãº/gi, 'u')
    .replace(/Ã±/gi, 'n')
    .replace(/Â¿/g, '')
    .replace(/Â¡/g, '')

    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

const pregunta =
  normalizar(preguntaOriginal);


// Si el carácter � ya llegó desde PowerShell,
// no se puede recuperar exactamente la letra original.
//
// Creamos una segunda versión exclusivamente
// para reconocer el dominio.
//
// Ejemplos:
// "pron�stico" -> "pronstico"
// "Jun�n"      -> "junn"

const preguntaDominio =
  pregunta.replace(/\uFFFD/g, '');


// ------------------------------------------------------
// 2. SOLICITUDES SENSIBLES / INTERNAS
// ------------------------------------------------------

// No bloquear palabras normales como "dame"
// o "prompt" de forma aislada.
//
// Solo se bloquea cuando la intención es claramente
// obtener secretos, credenciales o instrucciones internas.

const patronesBloqueados = [

  // ------------------------------------------
  // CREDENCIALES Y SECRETOS
  // ------------------------------------------

  /\bcodigo fuente\b/,
  /\bsource code\b/,

  /\bapi[\s_-]*key\b/,
  /\bclave api\b/,

  /\bcontrasena\b/,
  /\bpassword\b/,

  /\bcredenciales\b/,

  /\bsecret[\s_-]*key\b/,
  /\btoken secreto\b/,

  /\bvariables? de entorno\b/,

  /\.env\b/,

  /\bconnection string\b/,
  /\bcadena de conexion\b/,


  // ------------------------------------------
  // PROMPTS / INSTRUCCIONES INTERNAS
  // ------------------------------------------

  /\bprompt interno\b/,

  /\bsystem prompt\b/,

  /\bprompt del sistema\b/,

  /\binstrucciones internas\b/,


  // ------------------------------------------
  // INTENTOS DE IGNORAR LAS REGLAS
  // ------------------------------------------

  /\bignora\b.{0,60}\b(instrucciones|reglas|system prompt|prompt interno)\b/,

  /\bolvida\b.{0,60}\b(instrucciones|reglas|system prompt|prompt interno)\b/,

  /\bomita?\b.{0,60}\b(instrucciones|reglas|system prompt|prompt interno)\b/,


  // ------------------------------------------
  // PEDIR EXPLÍCITAMENTE EL PROMPT INTERNO
  // ------------------------------------------

  /\b(dame|muestrame|revela|ensename)\b.{0,60}\b(system prompt|prompt interno|prompt del sistema|instrucciones internas)\b/,


  // ------------------------------------------
  // PEDIR CREDENCIALES
  // ------------------------------------------

  /\b(muestrame|dame|revela)\b.{0,60}\bcredenciales\b/,


  // ------------------------------------------
  // SECRETOS DE SERVICIOS CONCRETOS
  // ------------------------------------------

  /\bpostgres\b.{0,40}\b(contrasena|password|credenciales)\b/,

  /\bopenrouter\b.{0,40}\b(key|api key|clave)\b/,

  /\blangfuse\b.{0,40}\b(key|api key|clave)\b/,

  /\bmaptiler\b.{0,40}\b(key|api key|clave)\b/
];


const esPeligrosa =
  patronesBloqueados.some(
    patron =>
      patron.test(pregunta)
  );


// ------------------------------------------------------
// 3. DOMINIO PERMITIDO DE AGROSMART
// ------------------------------------------------------

const patronesAgroSmart = [

  // ==========================================
  // PRECIOS Y MERCADO
  // ==========================================

  /precio/,
  /cuesta/,
  /costo/,
  /costaba/,
  /cotiz/,

  /mercado/,
  /mayorista/,

  /vender/,
  /venta/,

  /tendencia/,

  /subira/,
  /bajara/,

  /alza/,
  /baja/,


  // ==========================================
  // VOLUMEN Y ABASTECIMIENTO
  // ==========================================

  /volumen/,

  /tonelada/,

  /kilo/,
  /\bkg\b/,

  /ingreso/,
  /ingresaron/,

  /abastecimiento/,
  /desabastecimiento/,

  /camion/,

  /oferta/,


  // ==========================================
  // AGRICULTURA
  // ==========================================

  /agricola/,
  /agricultura/,

  /cultivo/,
  /producto/,

  /cosecha/,

  /productor/,


  // ==========================================
  // CLIMA
  // ==========================================

  /clima/,

  /climatic/,

  /condiciones climatic/,

  /temperatur/,

  /lluvia/,

  /precipit/,

  /humedad/,

  /sequia/,

  /helada/,

  /evapotranspir/,

  /meteorolog/,


  // "pronóstico" normal
  /pronost/,

  // Caso:
  // pron�stico -> pronstico
  /pronstic/,


  // Junín normal
  /junin/,

  // Caso:
  // Jun�n -> junn
  /\bjunn\b/,


  // ==========================================
  // SATELITAL
  // ==========================================

  /satelit/,

  /\bndvi\b/,

  /mapa/,

  /espacial/,

  /vegetacion/,


  // ==========================================
  // RAG / BOLETINES
  // ==========================================

  /boletin/,

  /midagri/,

  /\bgmml\b/,

  /gran mercado mayorista/,

  /\bmmf2\b/,

  /mercado de frutas/,


  // ==========================================
  // PRODUCTOS COMUNES
  // ==========================================

  /papa/,

  /cebolla/,

  /coliflor/,

  /tomate/,

  /zanahoria/,

  /beterraga/,

  /yuca/,

  /maiz/,

  /camote/,

  /aji/,

  /rocoto/,

  /zapallo/,

  /lechuga/,

  /acelga/,

  /sandia/,

  /ajo/
];


const perteneceAgroSmart =
  patronesAgroSmart.some(
    patron =>
      patron.test(pregunta) ||
      patron.test(preguntaDominio)
  );


// ------------------------------------------------------
// 4. DECISIÓN FINAL
// ------------------------------------------------------

let consultaPermitida = true;

let motivoBloqueo = null;


if (esPeligrosa) {

  consultaPermitida = false;

  motivoBloqueo =
    'solicitud_sensible_o_interna';

}

else if (!perteneceAgroSmart) {

  consultaPermitida = false;

  motivoBloqueo =
    'fuera_de_alcance';

}


// ------------------------------------------------------
// 5. SALIDA
// ------------------------------------------------------

return [{
  json: {

    ...$json,

    consulta_permitida:
      consultaPermitida,

    motivo_bloqueo:
      motivoBloqueo,


    // ------------------------------------------
    // CAMPOS TEMPORALES PARA DEPURACIÓN
    // ------------------------------------------
    //
    // Cuando termines todas tus pruebas puedes
    // eliminarlos sin afectar el funcionamiento.

    validacion_texto_normalizado:
      pregunta,

    validacion_texto_dominio:
      preguntaDominio
  }
}];

