/*
 AGROSMART INSIGHTS - WF2
 NORMALIZAR CLASIFICACION

 Prioridades:
 1. Consultas documentales RAG (Pipeline 6).
 2. Monitoreo satelital externo (WF3).
 3. Clima y efectos sobre cultivos.
 4. Volumen de ingreso.
 5. Precios semanales.
 6. Precios generales y comparaciones.
 7. Clasificacion original del agente.

 Compatible con AI Agent2 y AI Agent3.
*/

// ========================================
// 1. EXTRAER Y VALIDAR JSON DEL AGENTE
// ========================================

function extraerObjeto(valor) {

  if (
    valor !== null &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  ) {
    return { ...valor };
  }

  if (typeof valor !== 'string' || !valor.trim()) {
    throw new Error(
      'La salida del agente esta vacia o no es JSON.'
    );
  }

  let texto = valor.trim().replace(/^\uFEFF/, '');

  const bloque = texto.match(
    /```(?:json)?\s*([\s\S]*?)\s*```/i
  );

  if (bloque) {
    texto = bloque[1].trim();
  } else {
    const inicio = texto.indexOf('{');
    const fin = texto.lastIndexOf('}');

    if (inicio >= 0 && fin > inicio) {
      texto = texto.slice(inicio, fin + 1);
    }
  }

  let datos;

  try {
    datos = JSON.parse(texto);
  } catch (e) {
    throw new Error(
      'El agente no devolvio JSON valido: ' +
      e.message
    );
  }

  if (
    !datos ||
    typeof datos !== 'object' ||
    Array.isArray(datos)
  ) {
    throw new Error(
      'La clasificacion debe ser un objeto JSON.'
    );
  }

  const categorias = [
    'precio_puntual',
    'volumen_ingreso',
    'tendencia_prediccion',
    'clima',
    'analisis_satelital_riesgo',
    'general',
    'fuera_alcance'
  ];

  if (!categorias.includes(datos.tipo_consulta)) {
    throw new Error(
      'tipo_consulta no valido: ' +
      String(datos.tipo_consulta)
    );
  }

  if (
    datos.fecha != null &&
    !/^\d{4}-\d{2}-\d{2}$/.test(
      String(datos.fecha)
    )
  ) {
    throw new Error(
      'Fecha invalida. Se espera YYYY-MM-DD o null.'
    );
  }

  return datos;
}

// ========================================
// 2. NORMALIZACION DE TEXTO
// ========================================

function normalizar(texto) {
  return String(texto ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

// ========================================
// 3. REGIONES
// ========================================

const regiones = [
  'junin',
  'lima',
  'arequipa',
  'cusco',
  'puno',
  'huanuco',
  'ica',
  'piura',
  'la libertad',
  'lambayeque',
  'ancash',
  'ayacucho',
  'cajamarca',
  'huancavelica',
  'apurimac',
  'tacna',
  'moquegua',
  'tumbes',
  'amazonas',
  'san martin',
  'ucayali',
  'loreto',
  'madre de dios',
  'pasco'
];

// ========================================
// 4. PROCESAR CLASIFICACIONES
// ========================================

return $input.all().map(item => {

  const datos = extraerObjeto(
    item.json.output ?? item.json.text
  );

  const preguntaOriginal = String(
    $('Webhook').first().json.body?.pregunta ??
    $('Webhook').first().json.body?.question ??
    ''
  );

  const pregunta = normalizar(preguntaOriginal);

  if (!pregunta) {
    throw new Error(
      'No se encontro la pregunta del usuario.'
    );
  }

  const tipoOriginal = datos.tipo_consulta;

  // ------------------------------------
  // DETECCION DE INTENCIONES
  // ------------------------------------

  const hablaDeClima =
    /\b(clima|climatico|meteorologico|tiempo|lluvia|lluvias|precipitacion|precipitaciones|temperatura|temperaturas|humedad|helada|heladas|sequia|pronostico|evapotranspiracion)\b/
      .test(pregunta);

  const hablaDePrecios =
    /\b(precio|precios|costo|costos|costaba|cuesta|cotizacion|cotizaciones|vario|variaron|variacion)\b/
      .test(pregunta);


  const hablaDeVolumen =
    /\b(volumen|volumenes|toneladas|kilogramos ingresados|ingreso|ingresaron|abastecimiento|equivale|equivalen|equivalencia|equivalencias|conversion|convertir|cuantos kilogramos|cuantos kilos|cuantos kg|cuanto pesa|peso de un atado)\b/
      .test(pregunta);

  const consultaEquivalencia =
    /\b(equivale|equivalen|equivalencia|equivalencias|conversion|convertir|cuantos kilogramos|cuantos kilos|cuantos kg|cuanto pesa|peso de un atado)\b/
      .test(pregunta);


  const hablaDeMercados =
    /\b(mercado|mercados|gmml|mmf2|frutas|verduras)\b/
      .test(pregunta);

  const pideResumen =
    /\b(resumen|general|generales|panorama|situacion|como estan|comparacion|compara|comparar)\b/
      .test(pregunta);

  const consultaSemanal =
    /\b(ultimos?\s+7\s+dias|ultimos?\s+siete\s+dias|esta\s+semana|ultima\s+semana|semana\s+pasada|semanal)\b/
      .test(pregunta);

  const consultaSatelital =
    /\b(ndvi|satelital|satelite|satelites|imagen satelital|imagenes satelitales|cobertura vegetal|indice de vegetacion|teledeteccion)\b/
      .test(pregunta);

  // ------------------------------------
  // PRIORIDAD 1 - CONSULTAS RAG
  // ------------------------------------

  const mencionaDocumentos =
    /\b(boletin|boletines|documento|documentos|informe|informes|fuente documental|fuentes documentales)\b/
      .test(pregunta);

  const buscaContenido =
    /\b(informacion|dicen|dice|menciona|mencionan|contiene|contienen|aparece|aparecen|reporta|reportan|explica|explican|almacenado|almacenados|almacenada|almacenadas|segun)\b/
      .test(pregunta);

  // Solo enviar al RAG si la intencion
  // es consultar contenido documental.
  const consultaRAG =
    mencionaDocumentos && buscaContenido;

  if (consultaRAG) {

    datos.tipo_consulta = 'general';

    datos.consulta_semanal = false;

  }

  // ------------------------------------
  // PRIORIDAD 2 - MONITOREO SATELITAL
  // ------------------------------------

  else if (consultaSatelital) {

    // Se conserva la categoria para identificar
    // la solicitud, aunque WF3 sea independiente.
    datos.tipo_consulta =
      'analisis_satelital_riesgo';

    datos.consulta_semanal = false;

  }

  // ------------------------------------
  // PRIORIDAD 3 - CLIMA
  // ------------------------------------

  else if (
    hablaDeClima &&
    !hablaDePrecios &&
    !hablaDeVolumen
  ) {

    datos.tipo_consulta = 'clima';

    datos.consulta_semanal = false;

    if (consultaSemanal) {
      datos.periodo = 'esta semana';
    }

    // Recuperar region explicita si
    // no fue detectada por el agente.
    if (!datos.lugar) {

      const encontrada = regiones.find(r =>
        pregunta.includes(r)
      );

      if (encontrada) {
        datos.lugar = encontrada
          .replace(/\b\w/g, l => l.toUpperCase());
      }
    }

  }

  // ------------------------------------
  // PRIORIDAD 4 - VOLUMEN
  // ------------------------------------
  else if (
    consultaEquivalencia ||
    (hablaDeVolumen && !hablaDePrecios)
  ) {
    datos.tipo_consulta = 'volumen_ingreso';
    datos.consulta_semanal = false;
  }

  // ------------------------------------
  // PRIORIDAD 5 - PRECIOS SEMANALES
  // ------------------------------------

  else if (
    consultaSemanal &&
    hablaDePrecios
  ) {

    datos.tipo_consulta = 'precio_puntual';

    datos.consulta_semanal = true;

  }

  // ------------------------------------
  // PRIORIDAD 6 - MERCADO GENERAL
  // ------------------------------------

  else if (
    hablaDePrecios &&
    (
      /\b(precios?\s+generales?|general(?:es)?\s+de\s+precios?|panorama\s+de\s+precios?)\b/
        .test(pregunta)
      ||
      (
        pideResumen &&
        hablaDeMercados &&
        (
          !datos.producto ||
          /^(producto consultado|producto|general|ninguno)$/i
            .test(String(datos.producto).trim())
        )
      )
    )
  ) {

    datos.tipo_consulta =
      'tendencia_prediccion';

    datos.producto = null;

    datos.consulta_semanal = false;

  }

  // ------------------------------------
  // REGLA FINAL DE SEGURIDAD RAG
  // ------------------------------------

  // Evita que cualquier regla posterior o
  // salida incorrecta del agente desvie
  // una pregunta documental al Pipeline 2.

  if (consultaRAG) {

    datos.tipo_consulta = 'general';

    datos.consulta_semanal = false;

  }

  // ------------------------------------
  // RESULTADO Y DIAGNOSTICO
  // ------------------------------------

  console.log('AGROSMART CLASIFICACION', {
    pregunta: preguntaOriginal,
    clasificacion_agente: tipoOriginal,
    clasificacion_final: datos.tipo_consulta,
    consulta_rag: consultaRAG,
    consulta_satelital: consultaSatelital
  });

  return {
    json: {
      ...item.json,

      output: JSON.stringify(datos),

      producto: datos.producto ?? null,
      periodo: datos.periodo ?? null,
      fecha: datos.fecha ?? null,
      tipo_consulta: datos.tipo_consulta,
      lugar: datos.lugar ?? null,

      consulta_semanal:
        datos.consulta_semanal === true,

      consulta_rag: consultaRAG,

      clasificacion_original: tipoOriginal
    }
  };

});

// ============================================================
// AGROSMART S3-03 - VALIDAR RESPUESTA DEL LLM
// Mode: Run Once for All Items
// ============================================================

const e = $('Code in JavaScript2').first().json;

const modelo = String(
  $input.first()?.json?.text ??
  $input.first()?.json?.output ??
  $input.first()?.json?.response ??
  ''
).trim();

const normal = s => String(s ?? '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

function nf(valor, max = 2, min = 2) {
  const n = Number(valor);
  if (!Number.isFinite(n)) return 'sin dato';
  return n.toLocaleString('es-PE', {
    minimumFractionDigits: min,
    maximumFractionDigits: max
  });
}

function fechaEs(valor) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(valor ?? ''));
  if (!m) return 'fecha no disponible';

  const meses = [
    'enero','febrero','marzo','abril','mayo','junio',
    'julio','agosto','septiembre','octubre','noviembre','diciembre'
  ];

  const mes = Number(m[2]);
  if (mes < 1 || mes > 12) return 'fecha no disponible';

  return `${Number(m[3])} de ${meses[mes - 1]} de ${m[1]}`;
}

function fallbackEspecifico() {
  const analisis = Array.isArray(e.analisis) ? e.analisis : [];

  if (!analisis.length) {
    return (
      `No se encontraron registros suficientes para analizar ` +
      `${e.producto_solicitado || 'el producto solicitado'}. ` +
      `No es posible emitir una recomendación sin datos verificables.`
    );
  }

  const partes = [];

  if ((e.total_variedades_encontradas ?? 0) > 1) {
    partes.push(
      `Se encontraron varias variedades o registros relacionados con ` +
      `${e.producto_solicitado}. Se muestran hasta tres con los datos ` +
      `más completos y recientes.`
    );
  }

  for (const a of analisis) {
    partes.push(
      `**${a.producto} — ${a.mercado}**\n` +
      `Precio: S/ ${nf(a.precio_actual)} por ${a.unidad || 'unidad'} ` +
      `(${fechaEs(a.fecha_precio)}). ` +
      `Tendencia: ${a.tendencia || 'sin comparación'}.\n` +
      `Volumen: ${nf(a.volumen_ultimo_t, 3, 0)} toneladas ` +
      `(${fechaEs(a.fecha_volumen)}).`
    );

    if (a.estado === 'suficiente' && a.decision_base) {
      partes.push(`**Recomendación:** ${a.decision_base}.`);
    } else {
      partes.push(
        `**Recomendación:** datos insuficientes. ` +
        `${Array.isArray(a.faltantes) ? a.faltantes.join(' ') : ''}`
      );
    }
  }

  partes.push(
    'Esta evaluación es orientativa y se basa únicamente en precios, ' +
    'volúmenes y tendencias disponibles en AgroSmart; no incluye clima ' +
    'y no garantiza precios futuros.'
  );

  return partes.join('\n\n');
}

// ------------------------------------------------------------
// MODO GENERAL
// ------------------------------------------------------------

if (e.modo === 'general') {
  return [{
    json: {
      text: modelo || 'No se pudo generar el resumen general.',
      estado_recomendacion: 'no_aplica'
    }
  }];
}

// ------------------------------------------------------------
// MODO ESPECIFICO
// Guardrails sencillos contra respuestas incompatibles con el contexto.
// ------------------------------------------------------------

let respuesta = modelo;
let usarFallback = !respuesta;

const textoModelo = normal(respuesta);

// El Pipeline 3 no recibe clima. Si el modelo afirma haberlo usado,
// preferimos una respuesta deterministica antes que una alucinacion.
const mencionaClimaNoDisponible =
  /\b(clima|lluvia|lluvias|sequia|helada|heladas|precipitacion|meteorologic)/
    .test(textoModelo);

if (mencionaClimaNoDisponible) {
  usarFallback = true;
}

// Verificar que las decisiones emitidas por el modelo no contradigan
// las decisiones base calculadas para los casos suficientes.
const analisis = Array.isArray(e.analisis) ? e.analisis : [];
const decisionesPermitidas = [
  'vender ahora',
  'esperar y monitorear',
  'vender parcialmente y monitorear'
];

const decisionesEsperadas = new Set(
  analisis
    .filter(a => a.estado === 'suficiente' && a.decision_base)
    .map(a => normal(a.decision_base))
);

for (const decision of decisionesPermitidas) {
  if (!textoModelo.includes(decision)) continue;

  // Si no existe ninguna decision base valida, el LLM no debe
  // inventar una recomendacion. Si existen, solo puede usar las
  // decisiones calculadas previamente por el Code node.
  if (
    decisionesEsperadas.size === 0 ||
    !decisionesEsperadas.has(decision)
  ) {
    usarFallback = true;
  }
}

if (usarFallback) {
  respuesta = fallbackEspecifico();
}

return [{
  json: {
    text: respuesta,
    estado_recomendacion:
      analisis.some(a => a.estado === 'suficiente')
        ? 'evaluado'
        : 'insuficiente',
    validacion_llm:
      usarFallback ? 'fallback_aplicado' : 'respuesta_llm_aceptada'
  }
}];

// ======================================================
// AGROSMART WF2 - PREPARAR CLIMA V3
// Pipeline 4 - Clima
//
// Objetivos:
// - Reducir tokens enviados al LLM.
// - Separar histórico y pronóstico.
// - Detectar consultas generales, puntuales y día por día.
// - Tolerar problemas de codificación como "d�a por d�a".
// - Enviar todos los días únicamente cuando el usuario los solicita.
//
// Mode: Run Once for All Items
// ======================================================


// ======================================================
// 1. DATOS DE ENTRADA
// ======================================================

const registros = $input.all()
  .map(item => item.json ?? {})
  .filter(r =>
    r.fecha &&
    r.ubicacion
  );


const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);


// ======================================================
// 2. FUNCIONES AUXILIARES
// ======================================================

function num(v) {

  if (
    v === null ||
    v === undefined ||
    v === ''
  ) {
    return null;
  }

  const n = Number(v);

  return Number.isFinite(n)
    ? n
    : null;
}


function fechaISO(v) {

  return String(
    v ?? ''
  ).slice(0, 10);
}


function normalizar(texto) {

  return String(texto ?? '')

    // Errores comunes de UTF-8 / mojibake
    .replace(/Ã¡/gi, 'a')
    .replace(/Ã©/gi, 'e')
    .replace(/Ã­/gi, 'i')
    .replace(/Ã³/gi, 'o')
    .replace(/Ãº/gi, 'u')
    .replace(/Ã±/gi, 'n')

    .replace(/Â¿/g, '')
    .replace(/Â¡/g, '')

    .toLowerCase()

    .normalize('NFD')

    .replace(
      /[\u0300-\u036f]/g,
      ''
    )

    .trim();
}


function hoyLima() {

  const partes =
    new Intl.DateTimeFormat(
      'en-CA',
      {
        timeZone: 'America/Lima',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }
    ).formatToParts(
      new Date()
    );


  const valores =
    Object.fromEntries(
      partes.map(
        p => [
          p.type,
          p.value
        ]
      )
    );


  return (
    `${valores.year}-` +
    `${valores.month}-` +
    `${valores.day}`
  );
}


function sumarDias(
  fecha,
  dias
) {

  const d =
    new Date(
      `${fecha}T12:00:00Z`
    );


  d.setUTCDate(
    d.getUTCDate() + dias
  );


  return [
    d.getUTCFullYear(),

    String(
      d.getUTCMonth() + 1
    ).padStart(
      2,
      '0'
    ),

    String(
      d.getUTCDate()
    ).padStart(
      2,
      '0'
    )

  ].join('-');
}


function compacto(r) {

  return {

    fecha:
      fechaISO(
        r.fecha
      ),

    temperatura:
      num(
        r.temperatura
      ),

    precipitacion:
      num(
        r.precipitacion
      ),

    humedad:
      num(
        r.humedad
      ),

    evapotranspiracion:
      num(
        r.evapotranspiracion
      )
  };
}


function rango(valores) {

  const validos =
    valores.filter(
      v => v !== null
    );


  if (!validos.length) {

    return {
      min: null,
      max: null
    };
  }


  return {

    min:
      Math.min(
        ...validos
      ),

    max:
      Math.max(
        ...validos
      )
  };
}


// ======================================================
// 3. FECHA EXPLÍCITA
// ======================================================

function extraerFechaExplicita(
  textoNormal
) {

  // ------------------------------------------
  // Formato YYYY-MM-DD
  // ------------------------------------------

  const iso =
    textoNormal.match(
      /\b(\d{4}-\d{2}-\d{2})\b/
    );


  if (iso) {

    return iso[1];
  }


  // ------------------------------------------
  // Formato:
  // 3 de noviembre de 2026
  // ------------------------------------------

  const meses = {

    enero: 1,
    febrero: 2,
    marzo: 3,
    abril: 4,
    mayo: 5,
    junio: 6,
    julio: 7,
    agosto: 8,
    septiembre: 9,
    setiembre: 9,
    octubre: 10,
    noviembre: 11,
    diciembre: 12
  };


  const m =
    textoNormal.match(

      /\b(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)(?:\s+de\s+(\d{4}))?\b/

    );


  if (!m) {

    return null;
  }


  const hoy =
    hoyLima();


  const anio =
    Number(
      m[3] ??
      hoy.slice(
        0,
        4
      )
    );


  const mes =
    meses[
      m[2]
    ];


  const dia =
    Number(
      m[1]
    );


  return [

    anio,

    String(
      mes
    ).padStart(
      2,
      '0'
    ),

    String(
      dia
    ).padStart(
      2,
      '0'
    )

  ].join('-');
}


// ======================================================
// 4. NOMBRE DEL DÍA
// ======================================================

function nombreDia(
  fecha
) {

  const [
    anio,
    mes,
    dia
  ] =
    fecha
      .split('-')
      .map(Number);


  const fechaUTC =
    new Date(
      Date.UTC(
        anio,
        mes - 1,
        dia,
        12
      )
    );


  return (
    new Intl.DateTimeFormat(
      'es-PE',
      {
        weekday: 'long',
        timeZone: 'UTC'
      }
    )

      .format(
        fechaUTC
      )

      .normalize('NFD')

      .replace(
        /[\u0300-\u036f]/g,
        ''
      )

      .toLowerCase()
  );
}


// ======================================================
// 5. SEPARAR HISTÓRICOS Y PRONÓSTICOS
// ======================================================

const historicos =
  registros

    .filter(
      r =>
        String(
          r.tipo_dato ?? ''
        )
          .toLowerCase() ===
        'historico'
    )

    .sort(
      (a, b) =>
        fechaISO(
          b.fecha
        ).localeCompare(
          fechaISO(
            a.fecha
          )
        )
    );


const pronosticos =
  registros

    .filter(
      r =>
        String(
          r.tipo_dato ?? ''
        )
          .toLowerCase() ===
        'pronostico'
    )

    .sort(
      (a, b) =>
        fechaISO(
          a.fecha
        ).localeCompare(
          fechaISO(
            b.fecha
          )
        )
    )

    .map(
      compacto
    );


// ======================================================
// 6. UBICACIÓN
// ======================================================

const ubicacion =
  registros[0]?.ubicacion ??
  'No especificada';


const ciudadReferencia =
  registros[0]?.ciudad_referencia ??
  null;


// ======================================================
// 7. ÚLTIMO HISTÓRICO
// ======================================================

const ultimoHistorico =
  historicos.length

    ? compacto(
        historicos[0]
      )

    : null;


// ======================================================
// 8. NORMALIZAR PREGUNTA
// ======================================================

const textoOriginal =
  String(
    pregunta ?? ''
  ).toLowerCase();


const texto =
  normalizar(
    pregunta
  );


const hoy =
  hoyLima();


// ======================================================
// 9. ¿PIDE DESGLOSE DÍA POR DÍA?
// ======================================================

// Caso correcto:
//
// "día por día"
// "dia por dia"
// "cada día"
// "detalle diario"
//
// Caso con error UTF-8:
//
// "d�a por d�a"
//
// La segunda expresión tolera un carácter cualquiera
// entre "d" y "a".

const pideTodosLosDias =

  /\b(dia por dia|cada dia|diario|detalle diario|desglose diario|pronostico diario)\b/
    .test(
      texto
    )

  ||

  /d.a\s+por\s+d.a/
    .test(
      textoOriginal
    );


// ======================================================
// 10. DETECTAR FECHA OBJETIVO
// ======================================================

let fechaObjetivo =
  null;


// ------------------------------------------
// PASADO MAÑANA
// ------------------------------------------

if (
  /\bpasado manana\b/
    .test(
      texto
    )
) {

  fechaObjetivo =
    sumarDias(
      hoy,
      2
    );
}


// ------------------------------------------
// MAÑANA
// ------------------------------------------

else if (
  /\bmanana\b/
    .test(
      texto
    )
) {

  fechaObjetivo =
    sumarDias(
      hoy,
      1
    );
}


// ------------------------------------------
// HOY
// ------------------------------------------

else if (
  /\b(hoy|dia de hoy|fecha actual)\b/
    .test(
      texto
    )
) {

  fechaObjetivo =
    hoy;
}


// ------------------------------------------
// FECHA EXPLÍCITA
// ------------------------------------------

else {

  fechaObjetivo =
    extraerFechaExplicita(
      texto
    );
}


// ======================================================
// 11. DÍA DE LA SEMANA
// ======================================================

// Ejemplo:
// "¿Cómo estará el clima el martes?"

if (!fechaObjetivo) {

  const diasSemana = [

    'lunes',
    'martes',
    'miercoles',
    'jueves',
    'viernes',
    'sabado',
    'domingo'
  ];


  const diaPedido =
    diasSemana.find(
      d =>
        new RegExp(
          `\\b${d}\\b`
        ).test(
          texto
        )
    );


  if (diaPedido) {

    fechaObjetivo =

      pronosticos.find(

        r =>
          nombreDia(
            r.fecha
          ) ===
          diaPedido

      )?.fecha ??
      null;
  }
}


// ======================================================
// 12. MODO DE RESPUESTA
// ======================================================

const modoRespuesta =

  pideTodosLosDias

    ? 'diario'

    : fechaObjetivo

      ? 'puntual'

      : 'resumen';


// ======================================================
// 13. DETALLE DIARIO PARA EL LLM
// ======================================================

let detalleDiario =
  null;


// ------------------------------------------
// DÍA POR DÍA
// ------------------------------------------
//
// Enviar TODOS los pronósticos recuperados
// desde PostgreSQL.

if (
  modoRespuesta ===
  'diario'
) {

  detalleDiario =
    pronosticos;
}


// ------------------------------------------
// DÍA ESPECÍFICO
// ------------------------------------------

else if (
  modoRespuesta ===
  'puntual'
) {

  const encontrado =
    pronosticos.find(
      r =>
        r.fecha ===
        fechaObjetivo
    );


  // [] significa:
  // el usuario pidió esa fecha,
  // pero no existe en los datos recibidos.

  detalleDiario =
    encontrado

      ? [
          encontrado
        ]

      : [];
}


// ------------------------------------------
// CONSULTA GENERAL
// ------------------------------------------
//
// null significa que no hace falta enviar
// todas las filas al modelo.

else {

  detalleDiario =
    null;
}


// ======================================================
// 14. INDICADORES GENERALES
// ======================================================

const temperaturas =
  pronosticos.map(
    r =>
      r.temperatura
  );


const humedades =
  pronosticos.map(
    r =>
      r.humedad
  );


const evapotranspiraciones =
  pronosticos.map(
    r =>
      r.evapotranspiracion
  );


const precipitaciones =
  pronosticos.map(
    r =>
      r.precipitacion
  );


const rangoTemperatura =
  rango(
    temperaturas
  );


const rangoHumedad =
  rango(
    humedades
  );


const rangoEvapotranspiracion =
  rango(
    evapotranspiraciones
  );


// ======================================================
// 15. PRECIPITACIÓN
// ======================================================

const precipValidas =
  precipitaciones.filter(
    v =>
      v !== null
  );


const precipitacionMaxima =
  precipValidas.length

    ? Math.max(
        ...precipValidas
      )

    : null;


const fechasMayorPrecipitacion =

  precipitacionMaxima !== null &&
  precipitacionMaxima > 0

    ? pronosticos

        .filter(
          r =>
            r.precipitacion ===
            precipitacionMaxima
        )

        .map(
          r =>
            r.fecha
        )

        .slice(
          0,
          3
        )

    : [];


// ======================================================
// 16. FECHAS CON LLUVIA
// ======================================================

const fechasConPrecipitacion =
  pronosticos

    .filter(
      r =>
        r.precipitacion !== null &&
        r.precipitacion > 0
    )

    .map(
      r =>
        r.fecha
    );


// ======================================================
// 17. BALANCE PRECIPITACIÓN / EVAPOTRANSPIRACIÓN
// ======================================================

// Cuenta registros donde:
//
// precipitación < evapotranspiración
//
// Esto NO significa automáticamente sequía.

const diasBalanceHidricoNegativo =
  pronosticos.filter(

    r =>

      r.precipitacion !== null &&

      r.evapotranspiracion !== null &&

      r.precipitacion <
      r.evapotranspiracion

  ).length;


// ======================================================
// 18. TENDENCIA DE TEMPERATURA
// ======================================================

// Resume los datos recibidos.
// NO genera un pronóstico nuevo.

const primeraTemperatura =
  pronosticos.find(

    r =>
      r.temperatura !== null

  )?.temperatura;


const ultimaTemperatura =
  [...pronosticos]

    .reverse()

    .find(

      r =>
        r.temperatura !== null

    )?.temperatura;


let tendenciaTemperatura =
  null;


if (
  primeraTemperatura !== undefined &&
  ultimaTemperatura !== undefined
) {

  const diferencia =

    ultimaTemperatura -
    primeraTemperatura;


  if (
    Math.abs(
      diferencia
    ) < 0.5
  ) {

    tendenciaTemperatura =
      'estable';

  }

  else if (
    diferencia > 0
  ) {

    tendenciaTemperatura =
      'ascendente';

  }

  else {

    tendenciaTemperatura =
      'descendente';
  }
}


// ======================================================
// 19. RESUMEN DEL PRONÓSTICO
// ======================================================

const resumenPronostico =

  pronosticos.length

    ? {

        temperatura:
          rangoTemperatura,

        humedad:
          rangoHumedad,

        evapotranspiracion:
          rangoEvapotranspiracion,

        precipitacion_maxima:
          precipitacionMaxima,

        fechas_mayor_precipitacion:
          fechasMayorPrecipitacion,

        fechas_con_precipitacion:
          fechasConPrecipitacion,

        tendencia_temperatura:
          tendenciaTemperatura,

        dias_precipitacion_menor_et0:
          diasBalanceHidricoNegativo
      }

    : null;


// ======================================================
// 20. SALIDA COMPACTA PARA BASIC LLM CHAIN6
// ======================================================

return [{
  json: {

    // ------------------------------------------
    // CONSULTA
    // ------------------------------------------

    pregunta_usuario:
      pregunta,

    modo_respuesta:
      modoRespuesta,


    // ------------------------------------------
    // UBICACIÓN
    // ------------------------------------------

    ubicacion,

    ciudad_referencia:
      ciudadReferencia,

    hoy_lima:
      hoy,


    // ------------------------------------------
    // HISTÓRICO
    // ------------------------------------------

    ultimo_historico:
      ultimoHistorico,


    // ------------------------------------------
    // PRONÓSTICO
    // ------------------------------------------

    pronostico: {

      disponible:
        pronosticos.length > 0,

      dias_disponibles:
        pronosticos.length,

      desde:
        pronosticos[0]?.fecha ??
        null,

      hasta:
        pronosticos.at(-1)?.fecha ??
        null,

      fecha_solicitada:
        fechaObjetivo,

      resumen:
        resumenPronostico,


      // ========================================
      // SIGNIFICADO:
      //
      // null:
      // consulta general.
      //
      // []:
      // pidió un día puntual,
      // pero no existe ese día.
      //
      // [1 registro]:
      // consulta puntual.
      //
      // [varios registros]:
      // pidió día por día.
      // ========================================

      detalle_diario:
        detalleDiario
    },


    // ------------------------------------------
    // CONTROL
    // ------------------------------------------

    total_registros_recibidos:
      registros.length,

    total_historicos:
      historicos.length,

    total_pronosticos:
      pronosticos.length,

    sin_datos:
      registros.length === 0
  }
}];

// AGROSMART WF2 - RESPUESTA DE EQUIVALENCIAS
// Sin consumo de tokens de IA.

const filas = $input.all().map(item => item.json);

const validas = filas.filter(r =>
  r.producto &&
  r.unidad &&
  Number(r.equivalencia_kg) > 0
);

const pregunta = String(
  $('Webhook').first().json.body?.pregunta || ''
);

function formatear(numero, decimales = 2) {
  return Number(numero).toLocaleString('es-PE', {
    minimumFractionDigits: decimales,
    maximumFractionDigits: decimales
  });
}

if (validas.length === 0) {
  return [{
    json: {
      respuesta:
        'No se encontró una equivalencia comercial ' +
        'válida para el producto y la presentación ' +
        'solicitados en GMML ni MMF2.',
      estado: 'sin_datos',
      pregunta
    }
  }];
}

const respuestas = validas.map(r => {

  const kg = Number(r.equivalencia_kg);
  const gramos = kg * 1000;

  const fecha = String(r.fecha || '').slice(0, 10);

  return (
    `**${r.mercado}**\n` +
    `Un(a) ${String(r.unidad).toLowerCase()} de ` +
    `**${r.producto}** equivale a ` +
    `**${formatear(kg)} kg** ` +
    `(${formatear(gramos, 0)} gramos).\n` +
    `Fecha del registro: ${fecha}.`
  );
});

return [{
  json: {
    respuesta:
      respuestas.join('\n\n') +
      '\n\nFuente: MIDAGRI / AgroSmart Insights.',
    estado: 'ok',
    pregunta,
    mercados_con_datos: validas.map(r => r.mercado)
  }
}];

