parameters.jsCode:
const filas = $input.all().map(i => i.json ?? {});

const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);


// ================================================
// FUNCIONES AUXILIARES
// ================================================

function normalizar(v) {
  return String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}


function numero(v) {
  if (v === null || v === undefined || v === '') {
    return null;
  }

  const n = Number(v);

  return Number.isFinite(n) && n >= 0
    ? n
    : null;
}


function redondear(v, decimales = 3) {
  const n = numero(v);

  if (n === null) return null;

  const factor = 10 ** decimales;

  return Math.round(
    (n + Number.EPSILON) * factor
  ) / factor;
}


function formatear(v, maxDecimales = 3) {
  const n = numero(v);

  if (n === null) return null;

  return n.toLocaleString('es-PE', {
    minimumFractionDigits: 0,
    maximumFractionDigits: maxDecimales
  });
}


function fechaNatural(valor) {

  const match =
    /^(\d{4})-(\d{2})-(\d{2})/
      .exec(String(valor ?? ''));

  if (!match) return null;

  const meses = [
    'enero',
    'febrero',
    'marzo',
    'abril',
    'mayo',
    'junio',
    'julio',
    'agosto',
    'septiembre',
    'octubre',
    'noviembre',
    'diciembre'
  ];

  const mes = Number(match[2]);

  if (mes < 1 || mes > 12) {
    return null;
  }

  return (
    `${Number(match[3])} de ` +
    `${meses[mes - 1]} de ${match[1]}`
  );
}


function nombreMercado(mercado) {

  return mercado === 'MMF2'
    ? 'Mercado Mayorista de Frutas N.º 2 (MMF2)'
    : 'Gran Mercado Mayorista de Lima (GMML)';
}


// ================================================
// CLASIFICACIÓN
// ================================================

let clase = {};

try {

  const origen =
    $('Code - Normalizar clasificación')
      .first()
      .json;

  clase =
    typeof origen.output === 'string'
      ? JSON.parse(origen.output)
      : (origen.output ?? origen);

} catch (_) {

  try {

    const origen =
      $('Switch1')
        .first()
        .json;

    clase =
      typeof origen.output === 'string'
        ? JSON.parse(origen.output)
        : (origen.output ?? origen);

  } catch (_) {

    clase = {};
  }
}


const texto =
  normalizar(pregunta);


const productoSolicitado = String(
  clase.producto ??
  filas.find(f => f.producto)?.producto ??
  'producto consultado'
).trim();


// ================================================
// MERCADO SOLICITADO
// ================================================

const mencionaGMML =
  /\bgmml\b|gran mercado mayorista/
    .test(texto);


const mencionaMMF2 =
  /\bmmf2\b|\bmmf\b|mercado mayorista de frutas/
    .test(texto);


const pideComparacion =
  /compar|ambos mercados|dos mercados|entre mercados/
    .test(texto);


const solicitaAmbos =
  pideComparacion ||
  (mencionaGMML && mencionaMMF2);


// ================================================
// UNIDAD SOLICITADA
// ================================================

const pideKg =
  /\b(kilogramos?|kilos?|kg)\b/
    .test(texto);


// ================================================
// ¿EL USUARIO DIJO UNA FECHA?
// ================================================

// Una fecha normalizada significa fecha específica.
//
// "hoy" también se considera explícito.
// Sin fecha y sin "hoy" significa:
// usar último registro disponible.

const fechaExplicita =
  Boolean(clase.fecha) ||
  /\b(hoy|dia de hoy|fecha actual)\b/
    .test(texto);


// ================================================
// PREPARAR DATOS POR MERCADO
// ================================================

const mercados = [
  'GMML',
  'MMF2'
];


const resultados =
  mercados.map(mercado => {

    const filasMercado =
      filas.filter(
        f => f.mercado === mercado
      );


    const registros =
      filasMercado

        .filter(
          f => f.producto != null
        )

        .map(f => {

          const volumenT =
            numero(f.volumen_t);

          const volumenKgAlmacenado =
            numero(
              f.volumen_kg_almacenado
            );


          // Priorizar volumen_t.
          // Si no existe, recuperar desde volumen_kg.

          const toneladas =
            volumenT !== null
              ? volumenT
              : volumenKgAlmacenado !== null
                ? volumenKgAlmacenado / 1000
                : null;


          const kgCalculados =
            toneladas === null
              ? null
              : toneladas * 1000;


          return {

            mercado,

            fecha:
              f.fecha_consultada ?? null,

            producto:
              f.producto,

            producto_id:
              f.producto_id ?? null,

            unidad:
              f.unidad ?? null,

            volumen_t:
              toneladas === null
                ? null
                : redondear(toneladas),

            volumen_kg:
              kgCalculados === null
                ? null
                : redondear(kgCalculados),

            tiene_volumen:
              toneladas !== null,

            inconsistencia:
              volumenT !== null &&
              volumenKgAlmacenado !== null &&
              Math.abs(
                volumenKgAlmacenado -
                volumenT * 1000
              ) > 1
          };
        });


    const conVolumen =
      registros.filter(
        r => r.tiene_volumen
      );


    const subtotalT =
      conVolumen.reduce(
        (suma, r) =>
          suma + r.volumen_t,
        0
      );


    const coincidencias =
      Number(

        filasMercado.find(
          f =>
            f.total_coincidencias != null
        )?.total_coincidencias ?? 0
      );


    return {

      mercado,

      fecha_consultada:
        filasMercado.find(
          f => f.fecha_consultada
        )?.fecha_consultada ?? null,

      registros,

      registros_con_volumen:
        conVolumen.length,

      registros_sin_volumen:
        registros.length -
        conVolumen.length,

      filas_coincidentes_en_bd:
        coincidencias,

      consulta_limitada:
        coincidencias >
        registros.length,

      subtotal_t:
        conVolumen.length
          ? redondear(subtotalT)
          : null,

      subtotal_kg:
        conVolumen.length
          ? redondear(
              subtotalT * 1000
            )
          : null,

      sin_datos:
        registros.length === 0,

      tiene_inconsistencias:
        registros.some(
          r => r.inconsistencia
        )
    };
  });


// ================================================
// QUÉ MERCADOS MOSTRAR
// ================================================

let mercadosMostrar;


if (solicitaAmbos) {

  mercadosMostrar = [
    'GMML',
    'MMF2'
  ];

} else if (mencionaGMML) {

  mercadosMostrar = [
    'GMML'
  ];

} else if (mencionaMMF2) {

  mercadosMostrar = [
    'MMF2'
  ];

} else {

  // Si no especificó mercado,
  // mostrar solo mercados donde
  // realmente aparece el producto.

  mercadosMostrar =
    resultados

      .filter(
        r => !r.sin_datos
      )

      .map(
        r => r.mercado
      );
}


const seleccionados =
  resultados.filter(
    r =>
      mercadosMostrar.includes(
        r.mercado
      )
  );


// ================================================
// TEXTO DEL VOLUMEN
// ================================================

function textoVolumen(registro) {

  const toneladas =
    formatear(
      registro.volumen_t,
      3
    );

  const kg =
    formatear(
      registro.volumen_kg,
      0
    );


  if (
    toneladas === null ||
    kg === null
  ) {
    return null;
  }


  // Si pregunta específicamente en kg,
  // mostramos primero kg.

  return pideKg

    ? `${kg} kg (${toneladas} toneladas)`

    : `${toneladas} toneladas (${kg} kg)`;
}


// ================================================
// CONSTRUIR RESPUESTA
// ================================================

const partes = [];


// Ningún mercado tiene registros.

if (!seleccionados.length) {

  const fecha =
    clase.fecha
      ? fechaNatural(clase.fecha)
      : null;


  partes.push(

    fecha

      ? `No se encontraron registros de ${productoSolicitado} ` +
        `para el ${fecha} en GMML ni MMF2.`

      : `No se encontraron registros disponibles de ` +
        `${productoSolicitado} en GMML ni MMF2.`
  );

} else {

  for (
    const resultado
    of seleccionados
  ) {

    const mercadoNombre =
      nombreMercado(
        resultado.mercado
      );


    const fecha =
      fechaNatural(
        resultado.fecha_consultada
      );


    // ------------------------------------------
    // SIN REGISTROS
    // ------------------------------------------

  if (resultado.sin_datos) {

    // Si se solicitaron ambos mercados y uno no tiene registros,
    // informar la ausencia sin asumir que el volumen fue cero
    // ni atribuirla exclusivamente al tipo de mercado.

    if (resultado.mercado === 'GMML') {

      partes.push(
        fecha
          ? `En el ${mercadoNombre} no se encontraron registros ` +
            `de ingreso de ${productoSolicitado} para el ${fecha}.`
          : `En el ${mercadoNombre} no se encontraron registros ` +
            `disponibles de ingreso de ${productoSolicitado}.`
      );

    } else {

      partes.push(
        fecha
          ? `En el ${mercadoNombre} no se encontraron registros ` +
            `de ingreso de ${productoSolicitado} para el ${fecha}.`
          : `En el ${mercadoNombre} no se encontraron registros ` +
            `disponibles de ingreso de ${productoSolicitado}.`
      );
    }

    continue;
  }


    const conVolumen =
      resultado.registros.filter(
        r => r.tiene_volumen
      );


    // ------------------------------------------
    // HAY PRODUCTO PERO NO HAY VOLUMEN
    // ------------------------------------------

    if (!conVolumen.length) {

      partes.push(

        fecha

          ? `En ${mercadoNombre} existen registros de ` +
            `${productoSolicitado} del ${fecha}, pero el ` +
            `volumen de ingreso no fue informado.`

          : `En ${mercadoNombre} existen registros de ` +
            `${productoSolicitado}, pero el volumen de ingreso ` +
            `no fue informado.`
      );

      continue;
    }


    // ------------------------------------------
    // UN SOLO REGISTRO
    // ------------------------------------------

    if (
      resultado.registros.length === 1
    ) {

      const registro =
        resultado.registros[0];


      const volumen =
        textoVolumen(registro);


      // Fecha pedida por el usuario.

      if (fechaExplicita) {

        partes.push(

          `El ${fecha ?? 'día consultado'}, en ${mercadoNombre}, ` +
          `el ingreso registrado de ${registro.producto} ` +
          `fue de ${volumen}.`
        );

      }

      // Sin fecha:
      // último registro disponible.

      else {

        partes.push(

          `El último registro disponible de ${registro.producto} ` +
          `en ${mercadoNombre} corresponde al ` +
          `${fecha ?? 'registro más reciente'}: ${volumen}.`
        );
      }


    // ------------------------------------------
    // VARIOS REGISTROS / VARIEDADES
    // ------------------------------------------

    } else {

      const encabezado =
        fechaExplicita

          ? `Para el ${fecha ?? 'día consultado'}, ` +
            `en ${mercadoNombre}:`

          : `Último registro disponible en ${mercadoNombre}` +
            (fecha ? ` (${fecha})` : '') +
            ':';


      const detalles =
        resultado.registros.map(
          registro => {

            if (
              !registro.tiene_volumen
            ) {

              return (
                `- ${registro.producto}` +
                (
                  registro.unidad
                    ? ` (${registro.unidad})`
                    : ''
                ) +
                ': volumen no informado.'
              );
            }


            return (
              `- ${registro.producto}` +
              (
                registro.unidad
                  ? ` (${registro.unidad})`
                  : ''
              ) +
              `: ${textoVolumen(registro)}.`
            );
          }
        );


      partes.push(
        [
          encabezado,
          ...detalles
        ].join('\n')
      );


      // El subtotal se identifica
      // expresamente como subtotal,
      // nunca como total oficial.

      if (
        resultado.subtotal_t !== null
      ) {

        partes.push(

          `Subtotal de los registros con volumen disponible ` +
          `en ${resultado.mercado}: ` +
          `${formatear(resultado.subtotal_t, 3)} toneladas ` +
          `(${formatear(resultado.subtotal_kg, 0)} kg). ` +
          `Este subtotal no se presenta como el total oficial ` +
          `del mercado.`
        );
      }
    }


    // ==========================================
    // ADVERTENCIAS
    // ==========================================

    const advertencias = [];


    if (
      resultado.registros_sin_volumen > 0
    ) {

      advertencias.push(

        `${resultado.registros_sin_volumen} registro(s) ` +
        `no tienen volumen informado`
      );
    }


    if (
      resultado.consulta_limitada
    ) {

      advertencias.push(

        `la consulta recuperó ${resultado.registros.length} ` +
        `de ${resultado.filas_coincidentes_en_bd} coincidencias`
      );
    }


    if (
      resultado.tiene_inconsistencias
    ) {

      advertencias.push(

        'se detectó una inconsistencia entre toneladas ' +
        'y kilogramos almacenados'
      );
    }


    if (
      advertencias.length
    ) {

      partes.push(

        `Nota para ${resultado.mercado}: ` +
        `${advertencias.join('; ')}.`
      );
    }
  }

  // ================================================
  // CONTEXTO ENTRE MERCADOS
  // ================================================

  if (
    solicitaAmbos &&
    seleccionados.some(
      r => r.mercado === 'GMML' && r.sin_datos
    ) &&
    seleccionados.some(
      r => r.mercado === 'MMF2' && !r.sin_datos
    )
  ) {
    partes.push(
      'Como referencia, el GMML concentra principalmente ' +
      'hortalizas, tubérculos y otros productos agrícolas, ' +
      'mientras que el MMF2 está especializado en frutas.'
    );
  }
}


// ================================================
// FUENTE
// ================================================

partes.push(
  'Fuente: MIDAGRI / AgroSmart Insights.'
);


// ================================================
// SALIDA
// ================================================

return [{
  json: {

    respuesta:
      partes.join('\n\n'),

    estado:
      seleccionados.some(
        r => !r.sin_datos
      )
        ? 'ok'
        : 'sin_datos',

    pregunta_usuario:
      pregunta,

    producto_solicitado:
      productoSolicitado,

    mercados_consultados:
      mercadosMostrar,

    fecha_solicitada:
      clase.fecha ?? null
  }
}];
